SELECT c_customer_id, CONCAT(c_first_name, ' ', c_last_name) AS full_name, CASE WHEN c_birth_year < 1958 THEN 'Young' WHEN c_birth_year BETWEEN 1958 AND 1976 THEN 'Middle' ELSE 'Old' END AS age_group, (c_birth_month * 100) + c_birth_day AS birth_md, CASE WHEN d_holiday = 'N' THEN 'Holiday' ELSE 'Regular' END AS day_type, d_date, (c_current_cdemo_sk + c_current_hdemo_sk) * 2 AS demo_sum_twice FROM customer JOIN date_dim ON customer.c_first_shipto_date_sk = date_dim.d_date_sk WHERE c_preferred_cust_flag = 'Y'
